\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=18mm]{geometry}
\usepackage[table]{xcolor}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{tikz}
\usepackage{enumitem}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ---- Palette (deep navy + warm accents) ----
\definecolor{bg}{HTML}{0B1220}
\definecolor{text}{HTML}{F8FAFC}
\definecolor{muted}{HTML}{B6C2D1}
\definecolor{primary}{HTML}{0F2A4F}   % deep navy
\definecolor{secondary}{HTML}{F59E0B} % amber
\definecolor{accent}{HTML}{FB7185}    % coral
\definecolor{cool}{HTML}{38BDF8}      % sky

\pagecolor{bg}
\color{text}

% ---- Typography ----
\newcommand{\TitleFont}{\fontsize{62}{70}\selectfont\bfseries}
\newcommand{\AuthorFont}{\fontsize{26}{32}\selectfont}
\newcommand{\BigNum}{\fontsize{88}{92}\selectfont\bfseries}
\newcommand{\BigNumB}{\fontsize{72}{78}\selectfont\bfseries}
\newcommand{\H2}{\fontsize{30}{36}\selectfont\bfseries}
\newcommand{\Body}{\fontsize{22}{28}\selectfont}
\newcommand{\Small}{\fontsize{18}{22}\selectfont}

\setlist[itemize]{leftmargin=18pt, itemsep=4pt, parsep=0pt, topsep=2pt,
  label={\color{secondary}$\blacktriangleright$}}

% ---- Card styles (left accent stripe) ----
\tcbset{
  card/.style={enhanced, arc=0pt, boxrule=0pt, colback=white!3!bg,
    left=14pt, right=14pt, top=10pt, bottom=10pt, valign=top,
    drop shadow={opacity=0.22, shadow xshift=1.2mm, shadow yshift=-1.2mm}},
  stripeA/.style={card, borderline west={6pt}{0pt}{secondary}},
  stripeB/.style={card, borderline west={6pt}{0pt}{accent}},
  stripeC/.style={card, borderline west={6pt}{0pt}{cool}},
  stripeD/.style={card, borderline west={6pt}{0pt}{text}},
}

% ---- Simple infographic helpers (TikZ) ----
\newcommand{\iconrow}[3]{%
  % #1 total icons, #2 filled icons, #3 color
  \begin{tikzpicture}[x=5.0mm,y=5.0mm,baseline]
    \foreach \i in {1,...,#1}{
      \pgfmathparse{\i<=#2?1:0}
      \ifnum\pgfmathresult=1
        \fill[#3] (\i*1.1,0) circle (0.42);
      \else
        \draw[white!30] (\i*1.1,0) circle (0.42);
      \fi
    }
  \end{tikzpicture}%
}

\newcommand{\stackbar}[4]{%
  % #1 label, #2 value text, #3 fraction (0-1), #4 color
  \begin{tikzpicture}[x=1mm,y=1mm]
    \fill[white!12] (0,0) rectangle (170,10);
    \fill[#4] (0,0) rectangle ({170*#3},10);
    \node[anchor=west] at (0,14) {\Body\bfseries #1};
    \node[anchor=east] at (170,14) {\Body\bfseries #2};
  \end{tikzpicture}%
}

\begin{document}
\begin{tcbposter}[
  poster={columns=2,rows=20,spacing=6mm,showframe=false},
]

% ---- Title Bar (span=2) ----
\posterbox[enhanced,colback=primary,boxrule=0pt,arc=0pt,
  left=16pt,right=16pt,top=12pt,bottom=12pt,drop shadow={opacity=0.18},
]{name=title,column=1,span=2,between=top and row4}{%
  \TitleFont The State of Global Education\\[-2mm]
  {\AuthorFont\color{muted}Progress, gaps, and inequality in one view}
}

% ---- Stat banner (span=2) ----
\posterbox[enhanced,colback=white!2!bg,boxrule=0pt,arc=0pt,
  borderline west={8pt}{0pt}{accent},
  left=16pt,right=16pt,top=10pt,bottom=10pt,
]{name=dominant,column=1,span=2,between=row4 and row7}{%
  \H2\color{muted}Reality check (2023)\\[2mm]
  \BigNum\color{accent}244\,million\\[-1mm]
  {\H2 children are out of school worldwide.}\\[2mm]
  {\Body\color{muted}Primary-age: \textbf{~60M} \quad\textbar\quad Secondary-age: \textbf{~184M}}
}

% ---- Left column, row band A ----
\posterbox[stripeA]{name=progress,column=1,between=row7 and row12}{%
  \H2 Two centuries of educational expansion\\[2mm]
  {\Body\color{muted}From a rare privilege to a near-universal norm.}\\[4mm]

  {\Body\bfseries 1800: \color{muted}Adults with any formal education}\par
  \vspace{2mm}
  \iconrow{10}{2}{secondary}\hspace{6mm}{\BigNumB\color{secondary}< 1\,in\,5}\par
  \vspace{4mm}

  {\Body\bfseries Today: \color{muted}Adults with any formal education}\par
  \vspace{2mm}
  \iconrow{10}{8}{cool}\hspace{6mm}{\BigNumB\color{cool}> 4\,in\,5}\par

  \vspace{4mm}
  {\Small\color{muted}Education access expanded dramatically over 200 years—alongside rising global literacy.}
}

% ---- Right column, row band A ----
\posterbox[stripeC]{name=learningcrisis,column=2,between=row7 and row12}{%
  \H2 The learning crisis: enrollment $\neq$ learning\\[2mm]
  {\Body\color{muted}Being in school doesn’t guarantee foundational skills.}\\[4mm]

  \BigNumB\color{secondary}< 20\%\\[-1mm]
  {\Body children reach minimum reading proficiency}\par
  \vspace{2mm}
  {\Small\color{muted}In many low-income countries, fewer than 1 in 5 children can read with basic understanding by the end of primary school.}

  \vspace{4mm}
  {\Small\color{muted}\textbf{What this means:} classrooms without learning can hide behind improving enrollment numbers.}
}

% ---- Quality inequality (span=2) ----
\posterbox[stripeB]{name=quality,column=1,span=2,between=row12 and row17}{%
  \H2 Learning-adjusted years of schooling: a world divided\\[2mm]
  {\Body\color{muted}Quantity $\times$ quality — and the gap is enormous.}\\[4mm]

  \begin{center}
  \stackbar{Poorest countries}{\textbf{< 3 years}}{0.27}{accent}\\[10mm]
  \stackbar{South Asia \& Sub-Saharan Africa avg.}{\textbf{< 7 years}}{0.62}{secondary}\\[10mm]
  \stackbar{High-income countries}{\textbf{10+ years}}{0.92}{cool}
  \end{center}

  \vspace{2mm}
  {\Small\color{muted}Children in the poorest nations receive less than a third of the quality schooling available to peers in wealthy countries.}
}

% ---- Bottom-left: gender gap ----
\posterbox[stripeD]{name=gender,column=1,between=row17 and bottom}{%
  \H2 Closing the gender gap (with exceptions)\\[2mm]
  \begin{itemize}
    \item Primary and secondary enrollment gaps are \textbf{nearly closed} globally.
    \item In tertiary education, \textbf{women now exceed men} in enrollment.
    \item In some countries, girls still face severe barriers (e.g., \textbf{Afghanistan}).
  \end{itemize}

  \vspace{2mm}
  {\Small\color{muted}Progress is real — but not evenly shared.}
}

% ---- Bottom-right: takeaway / call to action ----
\posterbox[stripeA]{name=takeaway,column=2,between=row17 and bottom}{%
  \H2 The takeaway\\[2mm]
  {\Body\bfseries\color{text}The world built schooling at scale.}\par
  \vspace{2mm}
  {\Body\color{muted}Now the challenge is ensuring children can \textbf{attend} — and \textbf{learn}.}\par

  \vspace{5mm}
  \colorbox{primary!55}{\parbox{0.96\linewidth}{\vspace{2mm}\Body\bfseries\color{text}Remember this number: \color{accent}244\,million\color{text}.\vspace{2mm}}}

  \vspace{4mm}
  {\Small\color{muted}Source highlights: global education participation (1800→today), out-of-school estimates (2023), learning-adjusted years of schooling (2020), and reading proficiency in low-income contexts.}
}

\end{tcbposter}
\end{document}
